using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MultiStarCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/MultiStarCustomDescription", order = 0)]
public class MultiStarCustomDescription : MultipleActionCustomDescription
{
	private const string otherOrbsID = "OtherOrbs";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		MultiStarAction multiStarAction = battleAction as MultiStarAction;
		int amountWithoutEquation = GetAmountWithoutEquation(amountModified);
		string text = "";
		if (multiStarAction.OneOrbGoodAction)
		{
			text = text + GetActionFormattedDescription(multiStarAction.OneOrbGoodActionStarAbility, multiStarAction.GetBattleActionForOneOrbGoodDescription(), multiStarAction.EnableOneOrbGoodCustomAmount ? multiStarAction.OneOrbGoodCustomAmount : amountWithoutEquation, multiStarAction) + "\n";
			text += GetActionFormattedDescription(null, multiStarAction.GetBattleActionOtherOrbsOrbGoodDescription(), amountWithoutEquation, multiStarAction);
		}
		else
		{
			text = text + GetActionFormattedDescription(multiStarAction.CosmicOrbStarAbility, multiStarAction.CosmicOrbAction, amountWithoutEquation, multiStarAction) + "\n";
			text = text + GetActionFormattedDescription(multiStarAction.DevotionOrbStarAbility, multiStarAction.DevotionOrbAction, amountWithoutEquation, multiStarAction) + "\n";
			text = text + GetActionFormattedDescription(multiStarAction.KarmicOrbStarAbility, multiStarAction.KarmicOrbAction, amountWithoutEquation, multiStarAction) + "\n";
			text += GetActionFormattedDescription(multiStarAction.KnowledgeOrbStarAbility, multiStarAction.KnowledgeOrbAction, amountWithoutEquation, multiStarAction);
		}
		if (multiStarAction.MoveOrbsAfterCasting)
		{
			text = text + "\n\n" + multiStarAction.MoveOrbsAction.GetActionDescription(Mathf.Abs(multiStarAction.MoveOrbAmount));
		}
		return text;
	}

	private string GetActionFormattedDescription(StarAbility starAbility, BattleAction battleAction, int actionValue, MultiStarAction multiStarAction)
	{
		bool flag = starAbility == null;
		string actionDescription = battleAction.GetActionDescription(actionValue);
		string arg = (flag ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("OtherOrbs") : (starAbility.StarAbilityID.GetSpriteText() + starAbility.GetLocalizedNameWithoutModifiers()));
		string text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedActionTopicFormat();
		if (!flag)
		{
			text = text.Remove(0, 2);
		}
		string text2 = string.Format(text, arg, actionDescription);
		if (IsAddHighlight())
		{
			bool flag2 = false;
			if ((!multiStarAction.OneOrbGoodAction) ? multiStarAction.AddHighlightToDescription(starAbility) : ((!flag) ? multiStarAction.AddHighlightToDescription(starAbility) : (!multiStarAction.AddHighlightToDescription(multiStarAction.OneOrbGoodActionStarAbility))))
			{
				text2 = GetHighlightedDescription(text2);
			}
		}
		return text2;
	}
}
